            outline: none;
            border-color: #2e7d32;
        }
        .helper-text {
            font-size: 11px;
            color: #888;
            margin-top: 3px;
        }
        .required {
            color: #d32f2f;
        }
        button {
            background-color: #2e7d32;
            color: white;
            padding: 12px 30px;
            border: none;
            border-radius: 4px;
            font-size: 16px;
            cursor: pointer;
            transition: background-color 0.2s;
            margin: 20px auto 0;
            display: block;
        }
        button:hover {
            background-color: #1b5e20;
        }
        .success-message {
            display: none;
            background-color: #e8f5e9;
            color: #2e7d32;
            padding: 15px;
            border-radius: 4px;
            margin-top: 20px;
            text-align: center;
            border: 1px solid #c8e6c9;
        }
        @media (max-width: 600px) {
            .form-grid {
                grid-template-columns: 1fr 1fr;
            }
            .full-width {
                grid-column: 1 / -1;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Student Enrolment Signup - 2025-26 Admissions</h1>
        <form id="enrolmentForm">
            <!-- Student Details Section -->
            <div class="form-section">
                <h2>Student Details</h2>
                <div class="form-grid">
                    <div class="form-group">
                        <label>Student ID <span class="required">*</span></label>
                        <input type="text" name="studentId" placeholder="Auto-generated" readonly>
                    </div>
                    <div class="form-group">
                        <label>Name <span class="required">*</span></label>
                        <input type="text" name="name" placeholder="Full Name" required>
                    </div>
                    <div class="form-group">
                        <label>Gender <span class="required">*</span></label>
                        <select name="gender" required>
                            <option value="">-- Select --</option>
                            <option value="Male">Male</option>
                            <option value="Female">Female</option>
                            <option value="Other">Other</option>
                        </select>
                    </div>
                    <div class="form-group">
                        <label>Date of Birth <span class="required">*</span></label>
                        <input type="date" name="dob" required>
                    </div>
                    <div class="form-group">
                        <label>Class/Grade <span class="required">*</span></label>
                        <select name="class" required>
                            <option value="">-- Select --</option>
                            <option value="1">Class 1</option>
                            <option value="2">Class 2</option>
                            <option value="3">Class 3</option>
                            <option value="4">Class 4</option>
                            <option value="5">Class 5</option>
                            <option value="6">Class 6</option>
                            <option value="7">Class 7</option>
                            <option value="8">Class 8</option>
                            <option value="9">Class 9</option>
                            <option value="10">Class 10</option>
                            <option value="11">Class 11</option>
                            <option value="12">Class 12</option>
                        </select>
                    </div>
                    <div class="form-group">
                        <label>Village <span class="required">*</span></label>
                        <input type="text" name="village" placeholder="Village Name" required>
                    </div>
                </div>
            </div>

            <!-- Parent/Guardian Section -->
            <div class="form-section">
                <h2>Parent/Guardian Details</h2>
                <div class="form-grid">
                    <div class="form-group full-width">
                        <label>Parent/Guardian Name <span class="required">*</span></label>
                        <input type="text" name="parentName" placeholder="Full Name" required>
                    </div>
                    <div class="form-group">
                        <label>Parent Occupation</label>
                        <input type="text" name="parentOccupation" placeholder="Occupation">
                    </div>
                    <div class="form-group">
                        <label>Aadhaar Number <span class="required">*</span></label>
                        <input type="text" name="aadhaarNumber" pattern="'"\\d{4}[-]\\d{4}[-]\\d{4}\" placeholder=\"XXXX-XXXX-XXXX\" maxlength=\"14\" required>
                        <span class=\"helper-text\">Format: XXXX-XXXX-XXXX</span>
                    </div>
                </div>
            </div>

            <"'!-- Identification & Contact Section -->
            <div class="form-section">
                <h2>Identification & Contact</h2>
                <div class="form-grid">
                    <div class="form-group full-width">
                        <label>Phone Number <span class="required">*</span></label>
                        <input type="tel" name="phoneNumber" pattern="[0-9]{10}" placeholder="10-digit mobile number" required>
                    </div>
                    <div class="form-group">
                        <label>Enrolment Date</label>
                        <input type="date" name="enrolmentDate" value="2026-08-23" readonly>
                    </div>
                </div>
            </div>

            <button type="submit">Submit Enrolment</button>
        </form>
        <div id="successMessage" class="success-message">
            <strong>Enrolment submitted successfully!</strong> Your application has been received for 2025-26 admissions.
        </div>
    </div>

    <script>
        document.addEventListener('"'DOMContentLoaded', function() {
            const studentIdInput = document.querySelector('input[name=\"studentId\"]');
            studentIdInput.value = generateStudentId();

            document.querySelector('input[name=\"aadhaarNumber\"]').addEventListener('input', function(e) {
                let value = e.target.value.replace(/\\D/g, '');
                if (value.length > 12) value = value.slice(0, 12);
                e.target.value = value.match(/.{1,4}/g).join('-');
            });

            document.querySelector('input[name=\"phoneNumber\"]').addEventListener('input', function(e) {
                let value = e.target.value.replace(/\\D/g, '');
                if (value.length > 10) value = value.slice(0, 10);
                if (value.length > 5) {
                    value = value.slice(0, 5) + ' - ' + value.slice(5);
                }
                e.target.value = value;
            });

            document.getElementById('enrolmentForm').addEventListener('submit', function(e) {
                e.preventDefault();

                const formData = new FormData(this);
                const data = {
                    studentId: formData.get('studentId'),
                    name: formData.get('name'),
                    gender: formData.get('gender'),
                    dob: formData.get('dob'),
                    class: formData.get('class'),
                    village: formData.get('village'),
                    parentName: formData.get('parentName'),
                    parentOccupation: formData.get('parentOccupation') || '',
                    aadhaarNumber: formData.get('aadhaarNumber'),
                    phoneNumber: formData.get('phoneNumber'),
                    enrolmentDate: formData.get('enrolmentDate')
                };

                console.log('Enrolment Data:', data);

                document.getElementById('enrolmentForm').style.display = 'none';
                document.getElementById('successMessage').style.display = 'block';
                document.querySelector('.container').style.pointerEvents = 'none';
                document.querySelector('.container').style.opacity = '0.7';
            });

            function generateStudentId() {
                const idPrefix = 'STU-26-';
                const nextNum = 1001;
                return idPrefix + nextNum.toString().padStart(4, '0');
            }
        });
    </script>
</body>
</html>
HTMLEOF"

